			function fn_callCommCd() {
			    
			    /*공통 서비스 호출 (공통코드)*/
			    util.Submit.send(app, "subOnload", function(pbSuccess) {
			        if (pbSuccess) {
			            
			            /* 공통코드 미지원 필터(삭제, 미지원)*/
			            /* 2022-12-19 공통코드 필터 / 공통코드 삭제 or 미지원 저장 불가*/
			            var vcCmbList = AppUtil.getComponentList(app, "grpData", "combobox");
			            var vcRdoList = AppUtil.getComponentList(app, "grpData", "radiobutton");
			            var filterExp = "label.indexOf('삭제') < 0 && label.indexOf('미지원') < 0";
			            
			            for (var idx = 0; idx < vcCmbList.length; idx++) {
			                
			                var vcCmbId = vcCmbList[idx].id;
			                var vcCmbCtrol = app.lookup(vcCmbId);
			                
			                var cmbFbl = vcCmbCtrol.fieldLabel;
			                var cmbText = vcCmbCtrol.text;
			                
			                /* 코드필터*/
			                if (vcCmbId != "" && vcCmbId != null) {
			                    vcCmbCtrol.filterExp = filterExp;
			                }
			            }
			            for (var idx = 0; idx < vcRdoList.length; idx++) {
			                
			                var vcRdoId = vcRdoList[idx].id;
			                var vcRdoCtrol = app.lookup(vcRdoId);
			                
			                var rdoFbl = vcRdoCtrol.fieldLabel;
			                var rdoText = vcRdoCtrol.text;
			                
			                /* 코드필터*/
			                if (vcRdoId != "" && vcRdoId != null) {
			                    vcRdoCtrol.filterExp = filterExp;
			                }
			            }
			            
			            // 목록화면에서 상세에 setDtlInfo 함수실행요청시 subOnload 서브미션의
			            // done 여부를 알수 없기 때문에 redraw 적용
			            util.Control.redraw(app, "grpData");
			        }
			    });
			}

