			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    
			    
			    //담당자 체크
			    var dsPic = app.lookup("grdPic").dataSet;
			    if(dsPic.getRowCount() == 0) {
			        util.Msg.alert(app, "주담당자를 입력해주십시요.");
			        return false;
			    } else {
			        if(dsPic.getRowCount() == dsPic.getRowStatedCount(cpr.data.tabledata.RowState.DELETED)) {
			            util.Msg.alert(app, "주담당자는 반드시 1명 선택해 주어야 합니다.");
			            return false;
			        }

			        var nPchprsCnt = 0;
			        for(var i=0; i<dsPic.getRowCount(); i++) {
			            if(dsPic.getRowState(i) != cpr.data.tabledata.RowState.DELETED) {
			                if(dsPic.getValue(i, "PCHPRS_YN") == "Y") {
			                    nPchprsCnt++;
			                }
			            }
			        }

			        if(nPchprsCnt == 0) {
			            util.Msg.alert(app, "주담당자는 반드시 1명 선택해 주어야 합니다.");
			            return false;
			        } else if(nPchprsCnt > 1) {
			            util.Msg.alert(app, "주담당자는 한명만 등록할 수 있습니다.");
			            return false;
			        }    
			    }
			    
			    
			    /* 사후관리 등록 1건이상*/
			    var rdb1 = app.lookup("rdb1");
			    if(atfcMngCnt >= 1){
			        
			        if(rdb1.value == 'N'){
			            
			            var psTitle = "사후관리 등록";
			            var psMsgId = "사후관리가 " + atfcMngCnt.toString() + "건\n등록되어 있어 사후관리여부를 아니오로 수정 불가합니다.";
			            
			            util.Msg.alert(app, psMsgId, null, function(){
			                
			            }, psTitle);
			            return false;
			        }
			    }
			    
			    if (!util.validate(app, "grp4")) return false; // 종결상세정보    
			    
			    var vcMultifileUpload = app.lookup("cmnMultifileupload");
			            
			           var psMsgId = "종결 수정을 저장 하시겠습니까?"; 
			                            
			            util.Msg.confirm(app, psMsgId, null, function() {
			                vcMultifileUpload.send(doSave);
			            }, function() {
			                return false;
			            }, "저장확인");
			    
			}

